from fractions import Fraction

def pushforward(probs, X):
    """Distribution of X(w) when outcome w has chance probs[w]: a dict value -> Fraction."""
    dist = {}
    for w, p in probs.items():
        v = X(w)
        dist[v] = dist.get(v, Fraction(0)) + p
    return dist

def cdf(dist, x):
    """F(x) = chance of a value at most x, from a dict value -> Fraction."""
    return sum((p for v, p in dist.items() if v <= x), Fraction(0))
